// Reference: es-toolkit/compat, a lodash-4.17.21-faithful port (words, groupBy, isEmpty).
const ref = await import(pathToFileURL('C:/Users/user/AppData/Local/Temp/skill-eval-TcrDCQ/node_modules/es-toolkit/dist/compat/index.mjs').href);

let seed = 20240607;
const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
const pick = (s) => s[Math.floor(rnd() * s.length)];
const FULL = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 -_.';
const BIASED = 'aBZ9_ .';
const fail = [];
const eq = (a, b) => JSON.stringify(a) === JSON.stringify(b);

// 1. words: exhaustive over short strings from a transition-rich alphabet.
const SMALL = 'aA1 _.-B';
let count = 0;
const walk = (prefix, depth) => {
  if (!eq(tokens(prefix), ref.words(prefix))) fail.push(['words-exh', prefix]);
  count++;
  if (depth === 0) return;
  for (const c of SMALL) walk(prefix + c, depth - 1);
};
walk('', 5);
// 2. words: random lengths 0..40 over the full range alphabet and a biased one.
for (let i = 0; i < 200000; i++) {
  const len = Math.floor(rnd() * 41);
  let s = '';
  for (let j = 0; j < len; j++) s += pick(FULL);
  if (!eq(tokens(s), ref.words(s))) fail.push(['words-rand', s]);
  count++;
}
for (let i = 0; i < 100000; i++) {
  const len = Math.floor(rnd() * 41);
  let s = '';
  for (let j = 0; j < len; j++) s += pick(BIASED);
  if (!eq(tokens(s), ref.words(s))) fail.push(['words-biased', s]);
  count++;
}

// 3. byAge: random arrays of 0..12 rows in the stated domain.
const NAMES = ['jung', 'kim', 'lee', 'park', 'choi'];
const ri = (a, b) => a + Math.floor(rnd() * (b - a + 1));
for (let i = 0; i < 50000; i++) {
  const n = ri(0, 12);
  const rows = [];
  for (let j = 0; j < n; j++) rows.push({ id: ri(0, 9), name: pick(NAMES), age: ri(18, 60) });
  if (!eq(byAge(rows), ref.groupBy(rows, 'age'))) fail.push(['byAge', JSON.stringify(rows)]);
  count++;
}

// 4. isBlank: random JSON values within the stated domain (depth <= 2).
const randLeaf = () => pick([() => null, () => rnd() < 0.5, () => ri(-5, 99), () => pick(['', 'a', 'Id_MAX ', 'x y'])])();
const randVal = (d) => {
  const k = rnd();
  if (d === 0 || k < 0.5) return randLeaf();
  if (k < 0.75) {
    const n = ri(0, 3);
    return Array.from({ length: n }, () => randVal(d - 1));
  }
  const n = ri(0, 3);
  const o = {};
  for (let j = 0; j < n; j++) o[pick(['theme', 'a', 'b', 'c'])] = randVal(d - 1);
  return o;
};
for (let i = 0; i < 100000; i++) {
  const v = randVal(2);
  if (isBlank(v) !== ref.isEmpty(v)) fail.push(['isBlank', JSON.stringify(v)]);
  count++;
}

// 5. Hand-checked lodash expectations for isBlank edge values.
