  ['', true], ['a', false], [[], true], [[0], false], [[[]], false],
  [{}, true], [{ a: 1 }, false], [{ a: null }, false], [{ theme: [43, null, 89] }, false],
  [[{}], false],
];
for (const [v, want] of blankCases) if (isBlank(v) !== want) fail.push(['isBlank-table', JSON.stringify(v), want]);

// 6. Task examples.
const ex = [
  ['tokens Id_MAX ', eq(tokens('Id_MAX '), ['Id', 'MAX'])],
  ['tokens empty', eq(tokens(''), [])],
  ['isBlank theme', isBlank({ theme: [43, null, 89] }) === false],
  ['isBlank {}', isBlank({}) === true],
];
for (const [name, ok] of ex) if (!ok) fail.push(['example', name]);

console.log('checks run:', count);
console.log('tokens("Id_MAX ") =', JSON.stringify(tokens('Id_MAX ')), ' ref =', JSON.stringify(ref.words('Id_MAX ')));
console.log('failures:', fail.length);
for (const f of fail.slice(0, 15)) console.log(f);

